            # Update only bits 15:8
            self.regs[addr] = (self.regs[addr] & 0x00FF) | (data << 8)
        else:
            self.regs[addr] = data

    def reset_registers(self):
        for addr, reset_value in self.regs.items():
            if addr == 0x00:
                # RST bit clears itself after reset
                self.regs[addr] = reset_value & 0x7FFF
            else:
                self.regs[addr] = reset_value
